"use strict";
import { Token } from "@uniswap/sdk-core";
import { DoubleCurrencyLogo } from "components/Logo/DoubleLogo";
import PoolAndGaugeAddress from "components/PoolAndGaugeAddress";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useModalState } from "hooks/useModalState";
import { useMemo } from "react";
import { Button } from "tamagui";
import { Flex, Separator, Text, styled, useSporeColors } from "ui/src";
import { GoldenVerified, InfoCircleFilled } from "ui/src/components/icons";
import { ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { useIncentivizeContext } from "../ContextProvider";
export default function PoolInfoAndChange() {
  const colors = useSporeColors();
  const { selectedPool, setIncentivizeStep } = useIncentivizeContext();
  const { toggleModal: togglePoolInfoModal } = useModalState(ModalName.PoolInfo);
  const currencies = useMemo(() => {
    if (!selectedPool?.token0 || !selectedPool?.token1) return [void 0, void 0];
    try {
      const token0 = new Token(
        ABSTRACT_TESTNET_CHAIN_ID,
        selectedPool.token0.id,
        parseInt(selectedPool.token0.decimals),
        selectedPool.token0.symbol,
        selectedPool.token0.name
      );
      const token1 = new Token(
        ABSTRACT_TESTNET_CHAIN_ID,
        selectedPool.token1.id,
        parseInt(selectedPool.token1.decimals),
        selectedPool.token1.symbol,
        selectedPool.token1.name
      );
      return [token0, token1];
    } catch (error) {
      console.warn("Failed to create tokens for pool logos:", error);
      return [void 0, void 0];
    }
  }, [selectedPool?.token0, selectedPool?.token1]);
  const poolName = selectedPool?.token0?.symbol && selectedPool?.token1?.symbol ? `${selectedPool.token0.symbol}/${selectedPool.token1.symbol}` : "WETH/USDC";
  const poolType = selectedPool?.protocol === "V2" ? selectedPool?.type === "Stable" ? "Basic Stable" : "Basic Volatile" : "Concentrated Volatile";
  const ButtonContainer = styled(Button, {
    py: "$padding16",
    px: "$padding16",
    borderRadius: "$rounded16",
    transition: "all 0.3s ease",
    backgroundColor: "$surface3",
    hoverStyle: { backgroundColor: "$surface3Hovered" },
    $lg: {
      flexGrow: 1,
      flexBasis: 1
    }
  });
  return <Flex
    p={"$spacing24"}
    $md={{ p: "$spacing16" }}
    borderRadius={"$rounded12"}
    maxWidth={700}
    width={"100%"}
    backgroundColor={"$surface2"}
  >
      <Text variant="subheading1">Incentivise Pool</Text>

      <Separator my={"$spacing24"} $md={{ my: "$spacing24" }} width={"100%"} borderColor={"$surface3"} height={1} />

      <Flex group row justifyContent="space-between" gap={"$spacing18"} $lg={{ flexDirection: "column" }}>
        <Flex className="left" row gap={"$gap12"}>
          <DoubleCurrencyLogo currencies={currencies} size={34} />

          <Flex flexDirection="column" justifyContent="center" gap={"$gap4"}>
            <Flex row gap={"$gap8"} alignItems="center">
              <Text variant="subheading2">{poolName}</Text>
              {selectedPool?.gauge?.id && <GoldenVerified size="$icon.16" />}
              <MouseoverTooltip text="Pool Trading Fee" size={TooltipSize.Max} placement="top">
                <Text
    backgroundColor={"$surface3"}
    py={"$padding4"}
    px={"$padding8"}
    borderRadius={"$rounded8"}
    variant="body4"
    cursor="pointer"
    hoverStyle={{ backgroundColor: "$surface3Hovered" }}
  >
                  {(() => {
    if (selectedPool?.protocol === "V2") {
      return selectedPool?.type === "Stable" ? "0.05%" : "0.3%";
    } else {
      const tickSpacing = selectedPool?.tickSpacing || selectedPool?.gauge?.tickSpacing;
      if (tickSpacing) {
        const TICK_SPACING_TO_FEE = {
          1: 100,
          // 0.01%
          50: 500,
          // 0.05%
          100: 500,
          // 0.05%
          200: 3e3,
          // 0.3%
          2e3: 1e4
          // 1%
        };
        const feeBasisPoints = TICK_SPACING_TO_FEE[parseInt(tickSpacing)] || 3e3;
        return `${(feeBasisPoints / 1e4).toFixed(2)}%`;
      }
      return "0.3%";
    }
  })()}
                </Text>
              </MouseoverTooltip>
              <MouseoverTooltip
    text={<PoolAndGaugeAddress poolAddress={selectedPool?.id} gaugeAddress={selectedPool?.gauge?.id} />}
    size={TooltipSize.Max}
    placement="top"
  >
                <Flex transition="opacity 0.3s ease" opacity={0} $group-hover={{ opacity: 1 }}>
                  <InfoCircleFilled size={"$icon.16"} color={"$neutral2"} />
                </Flex>
              </MouseoverTooltip>
            </Flex>
            <Text variant="body4" fontWeight={"$medium"} color={"$neutral2"}>
              {poolType}
            </Text>
          </Flex>
        </Flex>
        <Flex className="right" row gap={"$gap12"} $lg={{ flex: 1 }}>
          <ButtonContainer onPress={togglePoolInfoModal}>
            <Text variant="buttonLabel4">Pool info</Text>
          </ButtonContainer>
          <ButtonContainer onPress={() => setIncentivizeStep("step-1")}>
            <Text variant="buttonLabel4">Change</Text>
          </ButtonContainer>
        </Flex>
      </Flex>
    </Flex>;
}
